2	import java.util.ArrayList;
3	import java.util.Deque;
4	import java.util.List;
5	
6	/**
7	 * Finds the articulation points (cut vertices) of an undirected graph using
8	 * Tarjan's depth-first search algorithm.
9	 *
10	 * <p>A vertex is an articulation point if removing it (and its incident edges)
11	 * increases the number of connected components of the graph. The algorithm runs
12	 * in {@code O(V + E)} time.
13	 *
14	 * <p>Instances are stateless and therefore reusable and thread-safe: each call to
15	 * {@link #find(Graph)} allocates its own traversal state.
16	 *
17	 * <p>The traversal is implemented with an explicit stack rather than recursion, so
18	 * it handles arbitrarily deep graphs without risking a {@link StackOverflowError}.
19	 */
20	public final class ArticulationPointFinder {
21	
22	    /**
23	     * Returns the articulation points of the given graph in ascending order.
24	     *
25	     * @param graph the graph to analyze
26	     * @return the sorted list of articulation-point vertices (empty if none)
27	     */
28	    public List<Integer> find(Graph graph) {
29	        return new Search(graph).run();
30	    }
31	
32	    /**
33	     * Holds the mutable depth-first-search state for a single {@link #find(Graph)}
34	     * invocation, keeping {@link ArticulationPointFinder} itself stateless.
35	     */
36	    private static final class Search {
37	
38	        private final Graph graph;
39	
40	        /** Discovery time of each vertex in the DFS traversal. */
41	        private final int[] discovery;
42	
43	        /** Lowest discovery time reachable from each vertex's DFS subtree. */
44	        private final int[] low;
45	
46	        private final boolean[] visited;
47	        private final boolean[] isArticulationPoint;
48	
49	        /** Monotonically increasing DFS timestamp counter. */
50	        private int timer;
51	
52	        Search(Graph graph) {
53	            int vertexCount = graph.vertexCount();
54	            this.graph = graph;
55	            this.discovery = new int[vertexCount];
56	            this.low = new int[vertexCount];
57	            this.visited = new boolean[vertexCount];
58	            this.isArticulationPoint = new boolean[vertexCount];
59	        }
60	
61	        List<Integer> run() {
62	            int vertexCount = graph.vertexCount();
63	            for (int u = 0; u < vertexCount; u++) {
64	                if (!visited[u]) {
65	                    explore(u);
66	                }
67	            }
68	
69	            List<Integer> result = new ArrayList<>();
70	            for (int u = 0; u < vertexCount; u++) {
71	                if (isArticulationPoint[u]) {
72	                    result.add(u);
73	                }
74	            }
75	            return result;
76	        }
77	
78	        /**
79	         * Explores the DFS tree rooted at {@code root} using an explicit stack.
80	         *
81	         * <p>The stack always holds the current root-to-node path, which lets each
82	         * vertex fold its low-link and cut-vertex verdict into its parent the moment
83	         * it is fully explored — the iterative equivalent of returning from a
84	         * recursive call.
85	         */
86	        private void explore(int root) {
87	            visited[root] = true;
88	            discovery[root] = low[root] = ++timer;
89	
90	            Deque<Frame> stack = new ArrayDeque<>();
91	            stack.push(new Frame(root, -1));
92	
93	            while (!stack.isEmpty()) {
94	                Frame frame = stack.peek();
95	                int u = frame.vertex;
96	                List<Integer> neighbors = graph.neighbors(u);
97	
98	                if (frame.nextNeighbor < neighbors.size()) {
99	                    int v = neighbors.get(frame.nextNeighbor++);
100	                    if (!visited[v]) {
101	                        frame.children++;
102	                        visited[v] = true;
103	                        discovery[v] = low[v] = ++timer;
104	                        stack.push(new Frame(v, u));
105	                    } else if (v != frame.parent) {
106	                        // Back edge: update the low-link, but ignore the edge to the parent.
107	                        low[u] = Math.min(low[u], discovery[v]);
108	                    }
109	                } else {
110	                    // u is fully explored; fold its result into its parent.
111	                    stack.pop();
112	                    foldIntoParent(u, frame, stack.peek());
113	                }
114	            }
115	        }
116	
117	        /**
118	         * Applies the post-order step for a fully explored vertex {@code u}: the DFS
119	         * root becomes a cut vertex with more than one child, while any other vertex
120	         * propagates its low-link upward and may mark its parent as a cut vertex.
121	         *
122	         * @param u           the vertex that has just finished exploring
123	         * @param frame       {@code u}'s traversal frame
124	         * @param parentFrame the frame of {@code u}'s parent, or {@code null} if
125	         *                    {@code u} is the DFS root
126	         */
127	        private void foldIntoParent(int u, Frame frame, Frame parentFrame) {
128	            if (frame.parent == -1) {
129	                // The DFS root is a cut vertex only if it has more than one DFS child.
130	                if (frame.children > 1) {
131	                    isArticulationPoint[u] = true;
132	                }
133	                return;
134	            }
135	
136	            int parent = frame.parent;
137	            low[parent] = Math.min(low[parent], low[u]);
138	
139	            // A non-root vertex is a cut vertex when one of its children's subtrees
140	            // cannot reach above it via a back edge.
141	            boolean parentIsRoot = parentFrame.parent == -1;
142	            if (!parentIsRoot && low[u] >= discovery[parent]) {
143	                isArticulationPoint[parent] = true;
144	            }
145	        }
146	    }
147	
148	    /** One vertex's state on the explicit DFS stack. */
149	    private static final class Frame {
150	
151	        final int vertex;
152	        final int parent;
153	
154	        /** Index of the next neighbor to visit from {@link #vertex}. */
155	        int nextNeighbor;
156	
157	        /** Number of DFS-tree children discovered from {@link #vertex}. */
158	        int children;
159	
160	        Frame(int vertex, int parent) {
161	            this.vertex = vertex;
162	            this.parent = parent;
163	        }
164	    }
165	}
