4	 * A small, dependency-free test runner for {@link ArticulationPointFinder} and
5	 * {@link Graph}. Run with {@code java ArticulationPointFinderTest}; it prints a
6	 * summary and exits with a non-zero status if any test fails.
7	 */
8	public final class ArticulationPointFinderTest {
9	
10	    private int passed;
11	    private int failed;
12	
13	    public static void main(String[] args) {
14	        ArticulationPointFinderTest tests = new ArticulationPointFinderTest();
15	        tests.run();
16	        System.out.printf("%n%d passed, %d failed%n", tests.passed, tests.failed);
17	        if (tests.failed > 0) {
18	            System.exit(1);
19	        }
20	    }
21	
22	    private void run() {
23	        emptyGraphHasNoArticulationPoints();
24	        singleVertexHasNoArticulationPoints();
25	        triangleHasNoArticulationPoints();
26	        pathExposesInteriorVertices();
27	        starCenterIsArticulationPoint();
28	        disconnectedComponentsHandledIndependently();
29	        rootIsArticulationPointOnlyWithMultipleChildren();
30	        exampleFromMainMatchesExpectedOutput();
31	        negativeVertexCountIsRejected();
32	        outOfRangeEdgeIsRejected();
33	        malformedEdgeIsRejected();
34	        finderIsReusableAcrossGraphs();
35	        deepGraphDoesNotOverflowTheStack();
36	
37	        // Multigraph cases: parallel edges and self-loops must not change the
38	        // articulation-point verdict. (A back edge to the immediate parent only
39	        // contributes disc[parent], which the algorithm's `>=` test absorbs.)
40	        parallelEdgesBetweenTwoVerticesHaveNoArticulationPoint();
41	        parallelEdgesAlongPathPreserveInteriorCutVertices();
42	        parallelEdgeAcrossTriangleHasNoArticulationPoint();
43	        selfLoopIsIgnored();
44	    }
