46	    private void emptyGraphHasNoArticulationPoints() {
47	        check("empty graph", find(new Graph(0)), List.of());
48	    }
49	
50	    private void singleVertexHasNoArticulationPoints() {
51	        check("single vertex", find(new Graph(1)), List.of());
52	    }
