59	    private void pathExposesInteriorVertices() {
60	        Graph path = Graph.fromEdges(4, new int[][] {{0, 1}, {1, 2}, {2, 3}});
61	        check("path 0-1-2-3", find(path), List.of(1, 2));
62	    }
