69	    private void disconnectedComponentsHandledIndependently() {
70	        // Two separate paths: 0-1-2 and 3-4-5; the middle of each is a cut vertex.
71	        Graph forest = Graph.fromEdges(6, new int[][] {{0, 1}, {1, 2}, {3, 4}, {4, 5}});
72	        check("disconnected paths", find(forest), List.of(1, 4));
