import java.util.*;

public class Oracle {
  // Components among all V vertices, optionally with one vertex or one edge-instance removed.
  static int components(int V, int[][] edges, int rmVertex, int rmEdge) {
    List<List<Integer>> adj = new ArrayList<>();
    for (int i=0;i<V;i++) adj.add(new ArrayList<>());
    for (int i=0;i<edges.length;i++){ if(i==rmEdge) continue; int a=edges[i][0],b=edges[i][1];
      if(a==rmVertex||b==rmVertex) continue; adj.get(a).add(b); adj.get(b).add(a); }
    boolean[] seen=new boolean[V]; int comp=0;
    for(int s=0;s<V;s++){ if(s==rmVertex||seen[s]) continue; comp++;
      Deque<Integer> st=new ArrayDeque<>(); st.push(s); seen[s]=true;
      while(!st.isEmpty()){int u=st.pop(); for(int w:adj.get(u)) if(!seen[w]&&w!=rmVertex){seen[w]=true;st.push(w);}}}
    return comp;
  }
  static Set<Integer> bruteAP(int V,int[][] e){ int base=components(V,e,-1,-1); Set<Integer> s=new TreeSet<>();
    for(int v=0;v<V;v++) if(components(V,e,v,-1)>base) s.add(v); return s; }
  static Set<String> bruteBridges(int V,int[][] e){ int base=components(V,e,-1,-1); Set<String> s=new TreeSet<>();
    for(int i=0;i<e.length;i++){ if(e[i][0]==e[i][1]) continue; if(components(V,e,-1,i)>base)
      s.add(Math.min(e[i][0],e[i][1])+"-"+Math.max(e[i][0],e[i][1])); } return s; }

  public static void main(String[] a){
    Random r=new Random(7);
    int trials=200000, apMiss=0, brMiss=0, withPar=0;
    for(int t=0;t<trials;t++){
      int V=2+r.nextInt(6); int E=r.nextInt(2*V+1);
      int[][] e=new int[E][2]; Map<String,Integer> seen=new HashMap<>(); boolean par=false;
      for(int i=0;i<E;i++){ int u=r.nextInt(V),v=r.nextInt(V); e[i]=new int[]{u,v};
        if(u!=v){String k=Math.min(u,v)+"-"+Math.max(u,v); if(seen.merge(k,1,Integer::sum)>1) par=true;} }
      if(par) withPar++;
      ConnectivityResult res=new GraphConnectivity().analyze(Graph.fromEdges(V,e));
      Set<Integer> ap=new TreeSet<>(res.articulationPoints());
      Set<String> br=new TreeSet<>(); for(Graph.Edge g:res.bridges()) br.add(Math.min(g.u(),g.v())+"-"+Math.max(g.u(),g.v()));
      Set<Integer> bAP=bruteAP(V,e); Set<String> bBr=bruteBridges(V,e);
      if(!ap.equals(bAP)){ if(apMiss++<5) System.out.println("AP MISMATCH "+Arrays.deepToString(e)+" got "+ap+" exp "+bAP); }
      if(!br.equals(bBr)){ if(brMiss++<5) System.out.println("BRIDGE MISMATCH "+Arrays.deepToString(e)+" got "+br+" exp "+bBr); }
    }
    System.out.println("trials="+trials+" withParallel="+withPar+" apMismatches="+apMiss+" bridgeMismatches="+brMiss);
  }
}
